import { buttonReset } from "../Button";
import { focus } from "../../helpers";
import { StyleFn } from "..";

export const Card: StyleFn = (theme, mode) => {
  const {
    color,
    elevation,
    font,
    size: { spacing, radius },
  } = theme;
  const { focusWithPseudo } = focus(theme, mode);
  const transitionDuration = "250ms";
  const transitionFunction = "cubic-bezier(.4,.8,0,.99)";

  const applyBoxShadow = (boxShadow: string, opacity: number) => {
    return {
      content: '""',
      position: "absolute",
      top: 0,
      right: 0,
      bottom: 0,
      left: 0,
      borderRadius: radius[6],
      boxShadow,
      transition: `opacity ${transitionDuration} ${transitionFunction}`,
      opacity,
      pointerEvents: "none",
    };
  };
  return {
    root: {
      position: "relative",
      boxSizing: "border-box",
      display: "block",
      minWidth: spacing[16],
      minHeight: spacing[16],
      maxWidth: "19.5rem",
      borderRadius: radius[6],
      color: color.text.neutral.default[mode],
      backgroundColor: color.surface.elevation[3][mode],
      textAlign: "left",
      // pseudo selectors with an opacity transition
      // more performant than using a transition on box-shadow
      "&:before": applyBoxShadow(elevation.level3, 1),
      "&:after": applyBoxShadow(elevation.level4, 0),
    },
    _actionable: {
      "&:hover:before, &:active:before": { opacity: 0 },
      "&:hover:after": { opacity: 1 },
      "&:active:after": applyBoxShadow(elevation.level5, 1),
    },
    _selected: {
      outline: `2px solid ${color.border.accent.focus[mode]}`,
    },
    translate: {
      position: "relative",
      "& $_actionable": {
        transition: `transform ${transitionDuration} ${transitionFunction}`,
      },
      "&:hover": {
        // prevent transition flickering when
        // by adding a 8px element at the bottom
        "&:after": {
          content: '""',
          position: "absolute",
          height: spacing[4],
          bottom: "-" + spacing[4],
          right: 0,
          left: 0,
        },
        "& $_actionable": {
          transform: `translateY(-${spacing[4]})`,
        },
      },
    },
    media: {
      display: "block",
      minHeight: spacing[112],
      width: "100%",
      backgroundSize: "cover",
      backgroundRepeat: "no-repeat",
      backgroundPosition: "center",
      borderRadius: `${radius[6]} ${radius[6]} 0 0`,
      // used when card-media is applied to an img
      // not IE11 compatible
      objectFit: "cover",
    },
    content: {
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      padding: spacing[24],
      "& p": {
        margin: 0,
      },
    },
    title: {
      fontSize: font.size["heading-6"],
      lineHeight: font.lineheight["heading-6"],
      marginBottom: spacing[8],
    },
    header: {
      display: "flex",
      alignItems: "center",
      padding: spacing[24],
      paddingBottom: 0,
      marginBottom: spacing[8],
      "& + $content": {
        paddingTop: 0,
      },
    },
    headerTitle: {
      fontSize: font.size["heading-6"],
      lineHeight: font.lineheight["heading-6"],
      marginBottom: 0,
    },
    headerIcon: {
      marginRight: spacing[16],
      fontSize: spacing[24],
      height: spacing[24],
    },
    headerAction: {
      marginLeft: "auto",
      marginRight: `-${spacing[8]}`,
    },
    actionArea: {
      ...buttonReset,
      extend: [focusWithPseudo({ 
        radius: radius[6], 
        pseudo: "before",
        offset: 2
      })],
      "&:focus-visible:after": {
        pointerEvents: "none",
      },
      borderRadius: radius[6],
      width: "100%",
      display: "block",
      textAlign: "inherit",
      whiteSpace: "normal",
      cursor: "pointer",
      "&:focus": {
        outline: 0,
      },
      "&:active": {
        backgroundColor: color.surface.elevation[5][mode],
      },
      "& $content": {
        paddingBottom: spacing[24],
      },
    },
    actions: {
      display: "flex",
      alignItems: "center",
      padding: spacing[24],
      paddingTop: spacing[8],
      justifyContent: "flex-end",
      "& > :not(:first-child)": {
        marginLeft: spacing[8],
      },
    },
  };
};
